  codes:[{sys:"HR",v:"Vietnam",c:"#7e56dc"},{sys:"Student system",v:"Viet Nam",c:"#0e9692"},{sys:"Research office",v:"VN",c:"#ee604e"},{sys:"Alumni office",v:"VNM",c:"#26a060"}],
