  goals:[["role","Linh's PhD adds a role, and no new number"],["wait","A likely match waits for Mei's office"],["other","The other Linh Nguyen becomes a person of her own"]],
  modeL:"The application",modes:[["create","Creates a person first"],["search","Searches before it creates"]],
  givenL:"It gives the search",base:2,scale:10,lo:60,hi:90,bands:{link:"link",review:"a person decides",apart:"not her"},
